  `ffcabs` varchar(3) NOT NULL,
  `ffcket` varchar(40) DEFAULT '',
  `ffcjns` varchar(1) DEFAULT '',
  `ffnpot` int DEFAULT '0',
  `ffcsat` varchar(5) DEFAULT '',
  `ffnjum1` int DEFAULT '0' COMMENT 'untuk jumlah per bulan',
