-- membuang struktur untuk table salary_new.sapermintaankaryawan
DROP TABLE IF EXISTS `sapermintaankaryawan`;
CREATE TABLE IF NOT EXISTS `sapermintaankaryawan` (
  `ffcidpermintaan` bigint NOT NULL AUTO_INCREMENT,
  `ffcnopermintaan` varchar(30) DEFAULT '',
  `ffdtglpermintaan` date DEFAULT NULL,
  `ffcnikrequester` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '',
  `ffckddepart` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '',
  `ffckdbagian` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '',
  `ffckdjabatan` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '',
  `ffnjumlah` int DEFAULT '0',
  `ffcjnskebutuhan` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '',
  `ffcprioritas` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '',
  `ffcstatuskaryawan` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '',
  `ffdtglbutuh` date DEFAULT NULL,
  `ffcalasan` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '',
  `ffcjustifikasi` text,
  `ffcpendidikan` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '',
  `ffcjurusan` varchar(70) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '',
  `ffnpengalaman` int DEFAULT NULL,
  `ffckompetensi` text,
  `ffcsertifikasi` text,
  `ffcdeskripsi` text,
  `ffctanggungjawab` text,
  `ffcpersyaratan` text,
  `ffcnikreplacement` varchar(6) DEFAULT '',
  `ffcalasanreplace` varchar(100) DEFAULT '',
  `ffdcreate` datetime DEFAULT NULL,
  `ffdupdate` datetime DEFAULT NULL,
  `ffcupdate` varchar(50) DEFAULT '',
  PRIMARY KEY (`ffcidpermintaan`),
  UNIQUE KEY `ffcnopermintaan` (`ffcnopermintaan`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

